# frozen_string_literal: true

require_relative "support/harness"

# The committed build artifacts `pulpmesh/templates.rb` and `pulpmesh/entities.rb`
# are generated by `rake generate`. Regenerating them needs Erubi and kramdown,
# which cannot be compiled — spinel resolves `require` at parse time, so even a
# guarded `require "erubi"` fails the build. The staleness diff therefore lives
# in `rake check`; what is checked here is what a compiled binary can check: the
# table and the render methods it was built with.
#
# `pulpmesh/assets.rb` is checked in assets_test.rb, a program of its own: one
# that reaches both the entity table and every asset segfaults on startup under
# spinel.

# The entity table came through the same codegen.
Harness.check("entity table is populated", Pulpmesh::Markdown::ENTITIES.size > 800, true)
Harness.check("entity table maps a known name", Pulpmesh::Markdown::ENTITIES["eacute"], 233)

# Every template has a render method, and each produces the document it should.
Harness.build("generated", Harness::FIXTURE) do |_site, out|
  Harness.check("post page is a document",
                File.read(File.join(out, "with-code.html")).start_with?("<!doctype html>"), true)
  Harness.check("index is a document",
                File.read(File.join(out, "index.html")).start_with?("<!doctype html>"), true)
  Harness.check("404 is a document",
                File.read(File.join(out, "404.html")).start_with?("<!doctype html>"), true)
  Harness.check("feed is xml",
                File.read(File.join(out, "rss.xml")).start_with?("<?xml version=\"1.0\""), true)
end
